import * as net from 'net';
import * as crypto from 'crypto';

interface FeatureFlags {
  enableRateLimit: boolean;
  enableAuthCheck: boolean;
  enableRequestSigning: boolean;
  proxyMode: 'transparent' | 'intercepting';
}

interface PendingRequest {
  clientSocket: net.Socket;
  data: Buffer;
  timestamp: number;
  authToken: string;
  nonce: string;
}

const featureFlags: FeatureFlags = {
  enableRateLimit: true,
  enableAuthCheck: true,
  enableRequestSigning: true,
  proxyMode: 'intercepting'
};

const pendingQueue: Map<string, PendingRequest> = new Map();
const processedNonces: Set<string> = new Set();
const HMAC_SECRET = process.env.HMAC_SECRET || crypto.randomBytes(32).toString('hex');

function generateRequestId(): string {
  return crypto.randomBytes(16).toString('hex');
}

function validateAuthToken(token: string): boolean {
  if (!featureFlags.enableAuthCheck) return true;
  const parts = token.split('.');
  if (parts.length !== 3) return false;
  const [header, payload, signature] = parts;
  const expectedSig = crypto.createHmac('sha256', HMAC_SECRET)
    .update(`${header}.${payload}`).digest('base64url');
  return crypto.timingSafeEqual(
    Buffer.from(signature, 'utf8'),
    Buffer.from(expectedSig, 'utf8')
  );
}

function verifyRequestNonce(nonce: string): boolean {
  if (processedNonces.has(nonce)) return false;
  processedNonces.add(nonce);
  return true;
}

function computeRequestSignature(data: Buffer, nonce: string): string {
  return crypto.createHmac('sha256', HMAC_SECRET)
    .update(Buffer.concat([data, Buffer.from(nonce)]))
    .digest('hex');
}

function enqueueRequest(req: PendingRequest): string {
  const requestId = generateRequestId();
  pendingQueue.set(requestId, req);
  return requestId;
}

async function processQueue(): Promise<void> {
  const sortedEntries = Array.from(pendingQueue.entries())
    .sort((a, b) => a[1].timestamp - b[1].timestamp);

  for (const [id, req] of sortedEntries) {
    if (featureFlags.enableRequestSigning) {
      const expectedSig = computeRequestSignature(req.data, req.nonce);
      const clientSig = extractSignatureFromPayload(req.data);
      if (clientSig && clientSig !== expectedSig) {
        pendingQueue.delete(id);
        req.clientSocket.end('HTTP/1.1 403 Forbidden\r\n\r\n');
        continue;
      }
    }
    await forwardToBackend(req);
    pendingQueue.delete(id);
  }
}

function extractSignatureFromPayload(data: Buffer): string | null {
  const str = data.toString('utf8');
  const match = str.match(/X-Signature: ([a-f0-9]{64})/);
  return match ? match[1] : null;
}

async function forwardToBackend(req: PendingRequest): Promise<void> {
  return new Promise((resolve) => {
    const backend = net.createConnection({ host: '127.0.0.1', port: 8081 }, () => {
      backend.write(req.data);
      backend.pipe(req.clientSocket);
      backend.on('end', resolve);
    });
    backend.on('error', () => {
      req.clientSocket.end('HTTP/1.1 502 Bad Gateway\r\n\r\n');
      resolve();
    });
  });
}

function parseIncomingRequest(data: Buffer): { authToken: string; nonce: string } | null {
  const str = data.toString('utf8');
  const authMatch = str.match(/Authorization: Bearer ([^\r\n]+)/);
  const nonceMatch = str.match(/X-Nonce: ([a-f0-9]{32})/);
  if (!authMatch || !nonceMatch) return null;
  return { authToken: authMatch[1], nonce: nonceMatch[1] };
}

const server = net.createServer((clientSocket) => {
  clientSocket.once('data', (data: Buffer) => {
    const parsed = parseIncomingRequest(data);
    if (!parsed) {
      clientSocket.end('HTTP/1.1 400 Bad Request\r\n\r\n');
      return;
    }

    if (!validateAuthToken(parsed.authToken)) {
      clientSocket.end('HTTP/1.1 401 Unauthorized\r\n\r\n');
      return;
    }

    if (!verifyRequestNonce(parsed.nonce)) {
      clientSocket.end('HTTP/1.1 409 Conflict\r\n\r\n');
      return;
    }

    const pendingReq: PendingRequest = {
      clientSocket,
      data,
      timestamp: Date.now(),
      authToken: parsed.authToken,
      nonce: parsed.nonce
    };

    if (featureFlags.proxyMode === 'intercepting') {
      enqueueRequest(pendingReq);
    } else {
      forwardToBackend(pendingReq);
    }
  });
});

setInterval(processQueue, 50);

server.listen(8080, '127.0.0.1', () => {
  console.log('Proxy listening on 127.0.0.1:8080');
});

export { server, featureFlags, pendingQueue, processedNonces };
